const items = $input.all();
const updatedItems = items.map((item) => {
  const whatsappNumber = item?.json?.whatsapp;
  if (whatsappNumber) {
    const numberWithoutCountryCode = whatsappNumber.substring(2);
    const updatedNumber =
      numberWithoutCountryCode.slice(0, 2) +
      "9" +
      numberWithoutCountryCode.slice(2);
    item.json.whatsapp = updatedNumber;
  }
  return item;
});
return updatedItems;

// -----------------------------------------------------------------------------
// 🔧 Funções auxiliares
// -----------------------------------------------------------------------------
function toObjectId(id) {
  // Just validate and return the 24-character hex string as-is
  return (typeof id === 'string' && /^[0-9a-fA-F]{24}$/.test(id))
    ? id
    : id;
}

function toNativeDate(value) {
  const d = new Date(value);
  return isNaN(d.getTime()) ? new Date() : d;
}

// -----------------------------------------------------------------------------
// 🔄 Processamento principal
// -----------------------------------------------------------------------------
const now = new Date();
const items = $input.all();

return items.map(item => {
  const raw = item.json.dados ?? item.json.output ?? item.json;
  const parsed = (typeof raw === 'string') ? JSON.parse(raw) : raw;

  return {
    json: {
      userId: toObjectId(parsed.userId),     // ✅ ObjectId real (não $oid)
      icon: parsed.icon || "",
      category: parsed.category || "",
      amount: Number(parsed.amount ?? 0),
      date: toNativeDate(parsed.date),
      details: parsed.details || "",
      tipoMovimentacao: parsed.tipoMovimentacao || "",
      createdAt: now,
      updatedAt: now,
      __v: 0
    }
  };
});

